		dimScores := scorer(req, snapshots)
		w := ws.weights[i]
		// Apply modulation: weight[0]=prefix-affinity, weight[1]=load-balance
		if i == 0 {
			w *= prefixBoost
		} else {
			w *= loadBoost
		}
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * w
		}
