	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		} else if scores[snap.ID] == bestScore && snap.EffectiveLoad() < snapshots[bestIdx].EffectiveLoad() {
